from itertools import combinations

def diff(a, b):
    """Return the circular difference in Z_10, in range 1-5"""
    d = abs(a - b) % 10
    return min(d, 10 - d)

def base_triple_diffs(a, b):
    """For base triple {0, a, b}, return the three differences"""
    return tuple(sorted([diff(0, a), diff(0, b), diff(a, b)]))

# Generate all possible base triples and their difference multisets
base_triples = []
for a in range(1, 10):
    for b in range(a+1, 10):
        d = base_triple_diffs(a, b)
        base_triples.append(((0, a, b), d))

print("Number of base triples:", len(base_triples))
print("First 10:")
for bt in base_triples[:10]:
    print(bt)

